const FINISH_MS = Object.freeze({widowsGrasp:2080, finalLament:3250, hit:950, death:3050});
const NAME_TO_CLASS = Object.freeze({widowsGrasp:'attack',finalLament:'special',hit:'hit',death:'death'});
