/**
 * Mount a standalone visual layer into a position:relative combat stage.
 * @param {Object} options
 * @param {HTMLElement} options.mount Stage element where 720×420 scene coordinates map to visuals.
 * @param {Function} [options.onContact] Called when the animation visually touches the target. Does not apply damage.
 * @param {Function} [options.onComplete] Called when the visual action ends.
 * @param {Object} [options.target] Scene coordinate {x,y}, default {x:193,y:251}.
 * @param {Object} [options.playerRipple] Optional adapter returned by createMagePsychicRipple().
 */
function createMourningLady({mount,onContact=()=>{},onComplete=()=>{},target={x:193,y:251},playerRipple=null}={}) {
  if (!(mount instanceof HTMLElement)) throw new TypeError('createMourningLady: mount must be an HTMLElement');
  const host=document.createElement('div');host.className='eoa-ml-v16';host.dataset.assetId='eoa.enemy.mourning_lady';
  host.style.cssText='position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:10';
  const shadow=host.attachShadow({mode:'open'});
  shadow.innerHTML='<style>'+STYLE_SHEET+'</style><div class="mlduel" style="--ml16-flight-dx:-264px;--ml16-flight-dy:0px;--ml16-sonar-dx:-330px;--ml16-sonar-dy:0px">'+SVG_MARKUP+'</div>';
  mount.appendChild(host);
  const root=shadow.querySelector('.mlduel');
  const svg=shadow.querySelector('.eoa-ml-scene');
  const impactWrappers=[...shadow.querySelectorAll('[data-eoa-ml-target]')];
  let current='idle',requestId=0,timers=[],destroyed=false;
  const id='mourning-lady-'+nextInstanceId++;
  const schedule=(fn,ms,request)=>{
    const t=setTimeout(()=>{if(!destroyed&&request===requestId)fn();},ms);
    timers.push(t);
  };
  const clear=()=>{requestId++;timers.forEach(clearTimeout);timers=[];};
  const ensure=()=>{if(destroyed)throw new Error('Mourning Lady instance has been destroyed');};
  const setTarget=({x,y})=>{
    ensure();x=Number(x);y=Number(y);
    if(!Number.isFinite(x)||!Number.isFinite(y)) throw new TypeError('target requires finite x and y in 720×420 scene units');
    root.style.setProperty('--ml16-flight-dx',`${x-457}px`);
    root.style.setProperty('--ml16-flight-dy',`${y-251}px`);
    root.style.setProperty('--ml16-sonar-dx',`${-330+x-193}px`);
    root.style.setProperty('--ml16-sonar-dy',`${y-251}px`);
    for(const wrapper of impactWrappers) wrapper.setAttribute('transform',`translate(${x-193} ${y-251})`);
    return {x,y};
  };
  const reset=()=>{
    ensure();clear();current='idle';
    root.classList.remove('attack','special','hit','death','no-impact');
    playerRipple?.stop?.();
  };
  const play=(action, options={})=>{
    ensure();
    if(action==='idle'||action==='reset'){reset();return;}
    const cssClass=NAME_TO_CLASS[action];
    if(!cssClass) throw new RangeError('Unknown Mourning Lady action: '+action);
    reset();
    if(options.target)setTarget(options.target);
    const didHit=options.hit!==false;
    if(!didHit)root.classList.add('no-impact');
    // Force layout so replaying the same animation restarts its SVG keyframes.
    void root.offsetWidth;
    root.classList.add(cssClass);
    current=action;
    const request=requestId;
    if(CONTACT_MS[action]!=null){
      schedule(()=>{
        if(didHit&&action==='finalLament')playerRipple?.trigger?.();
        onContact({assetId:'eoa.enemy.mourning_lady',action,hit:didHit,target:{...currentTarget},visualContactMs:CONTACT_MS[action]});
      },CONTACT_MS[action],request);
    }
    schedule(()=>{
      onComplete({assetId:'eoa.enemy.mourning_lady',action});
      if(action!=='death')reset();
    },FINISH_MS[action],request);
  };
  // Never keep player state inside the enemy module. Only visuals and events.
  let currentTarget={x:193,y:251};
  const setTargetWrapped=(pos)=>{currentTarget=setTarget(pos);return {...currentTarget};};
  // Keep target on the same stage scale as the sprite.
  setTargetWrapped(target);
  const originalPlay=play;
  return {id,element:host,shadowRoot:shadow,svg,
    get state(){return current;},
    get target(){return {...currentTarget};},
    setTarget:setTargetWrapped,
    play:(action,opts={})=>{if(opts.target)opts={...opts,target:setTargetWrapped(opts.target)};return originalPlay(action,opts);},
    reset,
    destroy(){if(destroyed)return;clear();playerRipple?.stop?.();host.remove();destroyed=true;}
  };
}

const MAGE_RIPPLE_MARKUP = "<g xmlns=\"http://www.w3.org/2000/svg\" class=\"ml15-psychic-body-ripple\" mask=\"url(#ml15-mage-silhouette)\" aria-hidden=\"true\">\n  <rect class=\"ml15-wash\" x=\"170\" y=\"56\" width=\"242\" height=\"380\" fill=\"#c0aaff\" opacity=\".28\"/>\n  <g class=\"ml15-ripple-front\" fill=\"none\" stroke-linecap=\"round\">\n    <path d=\"M400 52 C378 98 419 149 400 192 S419 269 396 310 S414 379 398 439\" stroke=\"#a69af5\" stroke-width=\"62\" opacity=\".67\" filter=\"url(#ml15-ripple-soft)\"/>\n    <path d=\"M400 52 C378 98 419 149 400 192 S419 269 396 310 S414 379 398 439\" stroke=\"#d1beff\" stroke-width=\"18\" opacity=\".84\"/>\n    <path d=\"M400 52 C378 98 419 149 400 192 S419 269 396 310 S414 379 398 439\" stroke=\"#f7f3ff\" stroke-width=\"3.2\" opacity=\".95\"/>\n  </g>\n  <g class=\"ml15-ripple-echo\" fill=\"none\" stroke-linecap=\"round\">\n    <path d=\"M403 56 C383 111 416 156 400 206 S417 288 398 334 S405 400 400 433\" stroke=\"#84b6ff\" stroke-width=\"37\" opacity=\".52\" filter=\"url(#ml15-ripple-soft)\"/>\n    <path d=\"M403 56 C383 111 416 156 400 206 S417 288 398 334 S405 400 400 433\" stroke=\"#b4d4ff\" stroke-width=\"9\" opacity=\".78\"/>\n  </g>\n  <g class=\"ml15-ripple-after\" fill=\"none\" stroke-linecap=\"round\">\n    <path d=\"M410 64 C392 119 420 162 405 215 S419 307 401 352 S411 406 400 438\" stroke=\"#dbd0ff\" stroke-width=\"16\" opacity=\".62\"/>\n    <path d=\"M410 64 C392 119 420 162 405 215 S419 307 401 352 S411 406 400 438\" stroke=\"#faf7ff\" stroke-width=\"2.1\" opacity=\".88\"/>\n  </g>\n</g>\n";
const MAGE_MASK_MARKUP = "<mask xmlns=\"http://www.w3.org/2000/svg\" id=\"ml15-mage-silhouette\" maskUnits=\"userSpaceOnUse\" x=\"160\" y=\"45\" width=\"260\" height=\"410\" style=\"mask-type:alpha\">\n  <use href=\"#ml15-mage-rig\"/>\n</mask>\n";
const MAGE_FILTER_MARKUP = "<filter xmlns=\"http://www.w3.org/2000/svg\" id=\"ml15-ripple-soft\" x=\"-75%\" y=\"-75%\" width=\"250%\" height=\"250%\"><feGaussianBlur stdDeviation=\"6\"/></filter>\n";
const MAGE_RIPPLE_CSS = `
.eoa-ml-ripple-host .ml15-psychic-body-ripple{opacity:0;pointer-events:none}
.eoa-ml-ripple-host[data-eoa-psychic-ripple="on"] .ml15-psychic-body-ripple{opacity:1}
.eoa-ml-ripple-host .ml15-wash{opacity:0}
.eoa-ml-ripple-host[data-eoa-psychic-ripple="on"] .ml15-wash{animation:eoa-ml-ripple-wash .78s ease-out both}
.eoa-ml-ripple-host .ml15-ripple-front,.eoa-ml-ripple-host .ml15-ripple-echo,.eoa-ml-ripple-host .ml15-ripple-after{opacity:0;transform-origin:0 0}
.eoa-ml-ripple-host[data-eoa-psychic-ripple="on"] .ml15-ripple-front{animation:eoa-ml-ripple-pass .72s cubic-bezier(.25,.02,.7,.97) both}
.eoa-ml-ripple-host[data-eoa-psychic-ripple="on"] .ml15-ripple-echo{animation:eoa-ml-ripple-pass .71s cubic-bezier(.25,.02,.7,.97) .10s both}
.eoa-ml-ripple-host[data-eoa-psychic-ripple="on"] .ml15-ripple-after{animation:eoa-ml-ripple-pass .68s cubic-bezier(.25,.02,.7,.97) .20s both}
@keyframes eoa-ml-ripple-pass{0%{opacity:0;transform:translateX(13px)}9%{opacity:1}75%{opacity:.95}100%{opacity:0;transform:translateX(-225px)}}
@keyframes eoa-ml-ripple-wash{0%{opacity:0}16%{opacity:.28}40%{opacity:.18}100%{opacity:0}}
`;
/**
 * Optional V15 psychic ripple adapter for the SAME Mage SVG rig used by the V16 workshop.
 * Requires the source Mage's coordinate system (roughly viewBox="150 30 300 425").
 * Do not use unmodified with other class rigs: supply a different player hit overlay there.
 */
function createMagePsychicRipple(mageSvg) {
  if(!(mageSvg instanceof SVGElement))throw new TypeError('createMagePsychicRipple expects the Mage SVG element');
  const rig=mageSvg.querySelector('#ml15-mage-rig')||mageSvg.querySelector('.rig');
  if(!rig)throw new Error('Mage artwork has no matching .rig element; ripple requires the V16 Mage source coordinates');
  const existing=mageSvg.querySelector('.ml15-psychic-body-ripple');
  const defs=mageSvg.querySelector('defs')||mageSvg.insertBefore(document.createElementNS(SVG_NS,'defs'),mageSvg.firstChild);
  const instanceKey='eoa-ml-'+nextInstanceId++;
  const oldRigId=rig.id;
  if(!rig.id)rig.id=instanceKey+'-rig';
  let ripple=existing,maskEl=null,filterEl=null;
  if(!ripple){
    // A new instance gets unique mask/filter IDs to avoid conflicting SVG defs.
    const maskId=instanceKey+'-mask',filterId=instanceKey+'-soft';
    maskEl=svgNode(MAGE_MASK_MARKUP.replaceAll('ml15-mage-silhouette',maskId).replaceAll('ml15-mage-rig',rig.id));
    filterEl=svgNode(MAGE_FILTER_MARKUP.replaceAll('ml15-ripple-soft',filterId));
    defs.append(maskEl,filterEl);
    ripple=svgNode(MAGE_RIPPLE_MARKUP.replaceAll('ml15-mage-silhouette',maskId).replaceAll('ml15-ripple-soft',filterId));
    mageSvg.appendChild(ripple);
  }
  const style=document.createElementNS(SVG_NS,'style');style.textContent=MAGE_RIPPLE_CSS;
  mageSvg.prepend(style);mageSvg.classList.add('eoa-ml-ripple-host');
  return {
    trigger(){mageSvg.removeAttribute('data-eoa-psychic-ripple');void mageSvg.getBoundingClientRect();mageSvg.setAttribute('data-eoa-psychic-ripple','on');},
    stop(){mageSvg.removeAttribute('data-eoa-psychic-ripple');},
    destroy(){mageSvg.removeAttribute('data-eoa-psychic-ripple');mageSvg.classList.remove('eoa-ml-ripple-host');style.remove();if(!existing){ripple.remove();maskEl?.remove();filterEl?.remove();}if(!oldRigId)rig.removeAttribute('id');}
  };
}

window.EOAMourningLadyV16={createMourningLady,createMagePsychicRipple};
